actions.script:
import groovy.json.JsonOutput
def runValue = ec.entity.makeValue('moqui.math.MathModelRun') .setAll([mathModelId: 'MM_DEVICE_GROUP_CONTINUITY', startTime: ec.user.nowTimestamp, parameters: JsonOutput.toJson([deviceId: deviceId]), hasError: 'N']) runValue.setSequencedIdPrimary() runValue.create() mathModelRunId = runValue.mathModelRunId
try { List members = ec.entity.find('moqui.device.DeviceGroupMember') .condition('deviceId', deviceId) .orderBy('sequenceNum') .list()
results = members.collect { member -> String criticalityEnumId = member.criticalityEnumId boolean essential = !criticalityEnumId || criticalityEnumId == 'DgmcEssential' [ memberDeviceId : member.memberDeviceId, purposeEnumId : member.purposeEnumId, criticalityEnumId: criticalityEnumId ?: 'DgmcEssential', continuityImpact: essential ? 'GROUP_STOPS' : 'GROUP_CONTINUES' ] }
ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one() .setAll([endDate: ec.user.nowTimestamp, results: JsonOutput.toJson(results)]) .update() } catch (Throwable t) { ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one() .setAll([endDate: ec.user.nowTimestamp, hasError: 'Y', errors: t.toString()]) .update() throw t }

import groovy.json.JsonOutput
def runValue = ec.entity.makeValue('moqui.math.MathModelRun') .setAll([mathModelId: 'MM_DEVICE_GROUP_NORM_COMPLIANCE', startTime: ec.user.nowTimestamp, parameters: JsonOutput.toJson([deviceId: deviceId]), hasError: 'N']) runValue.setSequencedIdPrimary() runValue.create() mathModelRunId = runValue.mathModelRunId
try { // The only 2 requirements with a real structural evidence signal today. Set segmentationFeatureIds = ['FEAT_IEC3333_SR_5_1', 'FEAT_IEC3333_SR_5_2'] as Set boolean hasZoneBoundaryMember = ec.entity.find('moqui.device.DeviceGroupMember') .condition('deviceId', deviceId) .condition('purposeEnumId', 'DgmpZoneBoundary') .list().size() > 0
List reqAppls = ec.entity.find('org.moqui.cyber.CyberDeviceGroupNormRequirementAppl') .condition('deviceId', deviceId) .conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp) .list()
results = [] reqAppls.each { reqAppl -> String featureGroupId = reqAppl.productFeatureGroupId as String List groupAppls = ec.entity.find('mantle.product.feature.ProductFeatureGroupAppl') .condition('productFeatureGroupId', featureGroupId) .conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp) .list() groupAppls.each { groupAppl -> String productFeatureId = groupAppl.productFeatureId as String def feature = ec.entity.find('mantle.product.feature.ProductFeature') .condition('productFeatureId', productFeatureId).one() String status if (segmentationFeatureIds.contains(productFeatureId)) { status = hasZoneBoundaryMember ? 'SATISFIED' : 'MISSING' } else { status = 'NoEvidenceSchema' } results.add([ productFeatureGroupId: featureGroupId, productFeatureId : productFeatureId, description : feature?.description, status : status ]) } }
ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one() .setAll([endDate: ec.user.nowTimestamp, results: JsonOutput.toJson(results)]) .update() } catch (Throwable t) { ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one() .setAll([endDate: ec.user.nowTimestamp, hasError: 'Y', errors: t.toString()]) .update() throw t }
